\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2804:\"\n<p class=\"wp-block-paragraph\"><p>In tutta Italia ci sono meetup WordPress!I meetup sono <strong>incontri gratuiti e aperti a tutti,</strong> in cui le community locali si incontrano per condividere conoscenze, conoscersi e fare rete.</p></p>\n\n\n\n<p class=\"wp-block-paragraph\">Se non sai cos’è un meetup <a href=\"https://it.wordpress.org/meetup/guida-ai-meetup-di-wordpress/\">leggi la nostra Guida ai meetup.</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Non sai quali meetup sono attivi in Italia? <a href=\"https://it.wordpress.org/meetup/\">Cerca il meetup più vicino a te.</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Nei prossimi giorni, <em>in ordine cronologico</em>, si incontrano le community di:</strong></p>\n\n\n\n<h2 class=\"wp-block-heading\">Milano</h2>\n\n\n\n<p class=\"wp-block-paragraph\">mer 13 mag, ore 19:00, &#8220;WordCamp Torino: com&#8217;è andata?&#8221; &#8211; <a href=\"https://www.meetup.com/wordpress-meetup-milano/events/314556705/\">Milano: iscriviti per partecipare</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Padova</h2>\n\n\n\n<p class=\"wp-block-paragraph\">gio 14 mag, ore 19:00, &#8221; Core Web Vitals: come migliorare le performance del tuo sito&#8221; &#8211; <a href=\"https://www.meetup.com/padova-wordpress-meetup/events/314672217/\">Padova: iscriviti per partecipare</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Pisa</h2>\n\n\n\n<p class=\"wp-block-paragraph\">gio 21 mag, ore 18:15, &#8220;Edit semantico, LSP e altre diavolerie: agenti AI per sviluppare in WP&#8221; &#8211; <a href=\"https://www.meetup.com/pisa-wordpress-meetup/events/314682017/\">Pisa: iscriviti per partecipare</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Roma</h2>\n\n\n\n<p class=\"wp-block-paragraph\">ven 22 mag, ore 18:00, &#8220;WordPress Morto! Trasforma il tuo sito in un agente autonomo&#8221; &#8211; <a href=\"https://www.meetup.com/romawordpress/events/314647831/\">Roma: iscriviti per partecipare</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Lecce</h2>\n\n\n\n<p class=\"wp-block-paragraph\">ven 22 mag, ore 18:00, &#8220;Ottimizzare un sito WordPress per la GEO&#8221; &#8211; <a href=\"https://www.meetup.com/wordpress-meetup-lecce/events/314739981/\">Lecce: iscriviti per partecipare</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Catania</h2>\n\n\n\n<p class=\"wp-block-paragraph\">gio 28 mag, ore 19:00, &#8220;WP Catania Vibe Coding in WP: dal prompt al plugin (senza fare disastri)&#8221; &#8211; <a href=\"https://www.meetup.com/meetup-wordpress-catania/events/314627984/\">Catania: iscriviti per partecipare</a></p>\n\n\n\n<div style=\"height:var(--wp--preset--spacing--50)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n\n\n\n<p class=\"has-text-align-center has-dark-blueberry-color has-blueberry-3-background-color has-text-color has-background has-link-color has-extra-large-font-size wp-block-paragraph\">… articolo in aggiornamento…</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:73:\"https://it.wordpress.org/news/2026/05/tutti-i-meetup-di-maggio-2026/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"4293\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:76:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:22:\"WordCamp Torino e sei!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:60:\"https://it.wordpress.org/news/2026/04/wordcamp-torino-e-sei/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"https://it.wordpress.org/news/2026/04/wordcamp-torino-e-sei/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sun, 19 Apr 2026 17:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:6:\"Eventi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"WordCamp\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://it.wordpress.org/?p=4284\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:341:\"L&#8217;8 e il 9 maggio 2026, si terrà il WordCamp Torino, il sesto della sua storia, a 10 anni dal primo indimenticabile WordCamp Torino 2016! Il programma è davvero superlativo: 3 sale, 25 speaker, 4 workshop, 1 tavolo di discussione. Con argomenti che coprono tutte le aree di interesse: dagli interventi più tecnici a quelli [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Laura Sacco\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2044:\"\n<p class=\"wp-block-paragraph\"><a href=\"https://torino.wordcamp.org/\">L&#8217;8 e il 9 maggio 2026, si terrà il WordCamp Torino</a>, il sesto della sua storia, a 10 anni dal primo indimenticabile WordCamp Torino 2016!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://torino.wordcamp.org/2026/programma/\">Il programma è davvero superlativo:</a> 3 sale, 25 speaker, 4 workshop, 1 tavolo di discussione. Con argomenti che coprono tutte le aree di interesse: dagli interventi più tecnici a quelli ispirazionali. Ce n&#8217;è per tutti i gusti e i livelli!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Poi ci sono gli <a href=\"https://torino.wordcamp.org/2026/sponsors/\">sponsor</a> che non vedono l&#8217;ora di incontrarti e mostrarti i loro servizi (e le offerte speciali per il WCTRN ;))</p>\n\n\n\n<p class=\"wp-block-paragraph\">Infine, ma non ultimo, ampio spazio al networking: il vero valore aggiunto di ogni WordCamp in presenza. Persone che lavorano con WordPress, o che semplicemente lo usano e amano il più diffuso CMS di internet!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Che tu sia agli inizi, oppure lavori da anni con WordPress, non puoi perdere l&#8217;occasione! <a href=\"https://torino.wordcamp.org/2026/tickets/\">Qui puoi comprare il tuo biglietto.</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Vuoi saperne di più?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Allora non mancare l&#8217;appuntamento live (in presenza e in streaming) organizzato dal team dietro il <a href=\"https://www.meetup.com/it-it/wordpress-meetup-torino/events/314052178/\">Torino WordPress Meetup</a> il prossimo<strong> 23 aprile 2026, alle ore 18:30.</strong> <a href=\"https://torino.wordcamp.org/2026/il-wordcamp-che-verra/\">Sul sito del WordCamp Torino trovi tutte le informazioni.</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Io e tutto <a href=\"https://torino.wordcamp.org/2026/organizers/\">il team del WordCamp Torino</a> siamo entusiasti e non vediamo l&#8217;ora di incontrarti. Ci sarai?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Laura (LO) e il team di WCTRN</em></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:65:\"https://it.wordpress.org/news/2026/04/wordcamp-torino-e-sei/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"4284\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:4:\"href\";s:35:\"https://it.wordpress.org/news/feed/\";s:3:\"rel\";s:4:\"self\";s:4:\"type\";s:19:\"application/rss+xml\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:44:\"http://purl.org/rss/1.0/modules/syndication/\";a:2:{s:12:\"updatePeriod\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"\n	hourly	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:15:\"updateFrequency\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"\n	1	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpre